/** A stable unit projection is not compound-residual family qualification. */
public final class ContextUniversalCompoundResidualEvidenceRunner {
    static int checks;static final int WORK=64000000;static final String P="!@u p(u);",RULE="!@x p(x)&&b(x)->r(x);";
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static Result close(Snapshot x,Snapshot a,Packet p){ContextUniversalNativeRows.Result rows=ContextUniversalNativeRows.inspect(x,a,64,WORK);require(rows.classified&&rows.withinShape,rows.reason);Result r=ContextUniversalFrozenConstraints.closeSignedInstantiatedUnits(rows,p,null,null,16,16,512,256,WORK);require(r.closed,r.reason);ContextUniversalFrozenConstraints.check(r,16,()->{});return r;}
    static ContextUniversalSignedUnitRounds.Result run(Snapshot x,List<Snapshot> cuts,Packet p,int bound){return ContextUniversalSignedUnitRounds.runInstantiatedUnits(x,cuts,p,Collections.emptyMap(),null,ContextUniversalSignedFixedApplicationRoundsRunner.limits(bound),8,WORK);}
    static Residual shape(){try{return ContextUniversalInputResiduals.schema(bind(false,"!@x b(x)->r(x);").primary.get(0).clauses.get(0),()->{});}catch(Exception e){throw new IllegalStateException(e);}}
    static Proof residual(Result r,Set<Source> sources){Residual wanted=shape();return r.proofs.stream().filter(v->v.clause!=null&&v.clause.equivalent(wanted,()->{})&&v.support.sources.equals(sources)).findFirst().get();}
    static void nativeDonor(Snapshot x,Snapshot a,Packet p,Proof proof)throws Exception {
        Replay replay=ContextWitnessResultTransport.restore(p,WORK);List<Entry> originals=new ArrayList<>(x.primary);originals.addAll(a.primary);try(ContextProductionCapture c=ContextProductionCapture.begin(replay.mind,10000)){c.observeSchemaInteractions();for(Entry e:originals)c.replay(replay.mind,e.source,e.statement);replay.mind.setQueryPass(QueryPass.ACCEPT);replay.mind.link(null,false);require(!replay.mind.analyze(null,false),"native donor cut consistent");ContextUniversalSchemaInteractionAudit.Result audit=ContextUniversalSchemaInteractionAudit.inspect(replay,c,originals,WORK);require(audit.observedComplete,audit.reason);require(audit.obligations.stream().anyMatch(o->o.unifiable&&o.resolvent!=null&&ContextUniversalInputResiduals.schema(o.resolvent,()->{}).equivalent(proof.clause,()->{})&&o.sourceAlternatives.contains(proof.support.sources)),"actual native schema encounter agrees with the checked principal residual and complete Sources");require(!c.snapshot().gaps.isEmpty(),"native schema encounter remains an obligation with unresolved capture gaps, not stored knowledge/full coverage");}
    }
    static void nativeReceiver(Snapshot x,Snapshot b,Proof proof,boolean with)throws Exception {
        User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);try(ContextProductionCapture c=ContextProductionCapture.begin(m,10000)){c.observeSchemaInteractions();for(Entry e:x.primary)c.replay(m,e.source,e.statement);for(Entry e:b.primary)c.replay(m,e.source,e.statement);Input imported=with?c.replayTypedInput(m,proof.clause,Collections.singletonList(proof.support),Collections.emptyMap(),()->{}):null;if(with)require(imported.source==null&&imported.typedClause.equivalent(proof.clause,()->{}),"diagnostic replay uses actual typed proof/support, no fabricated per-clause Source");m.setQueryPass(QueryPass.CHECK);m.link(null,false);require(m.analyze(null,false)==with,"actual B-X is consistent until the actual X-dependent residual is replayed");ContextProductionCapture.Snapshot observed=c.snapshot();require(observed.gaps.isEmpty(),"ordinary receiver diagnostic capture has no gaps");if(with)require(observed.applications.stream().anyMatch(e->e.nativeRule==imported.nativeRule&&e.steps==1&&e.premises.size()==1&&e.producerSupports.contains(proof.support)),"actual receiver application retains derived producer depth/whole Sources, no depth reset");require(observed.inputs.stream().noneMatch(i->i.source!=null&&proof.support.sources.contains(i.source)&&!i.source.localX),"receiver never replays original foreign A row or a fake Source for its residual");}
    }
    static void one(boolean bundled)throws Exception {
        String text=bundled?"!@x (p(x)&&b(x)->r(x)) && (p(x)&&c(x)->s(x)) && hidden(99);":RULE;Snapshot x=bind(true,"!anchor(1);"+P),a=bind(false,text),b=bind(false,"!b(1); !~r(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);Source ps=ContextPrivateWitnessPoolRunner.source(x,P),as=a.primary.get(0).source;Set<Source> base=new HashSet<>(Arrays.asList(ps,as));Proof carried=null;Result receiver=null;ContextUniversalSignedUnitRounds.Result first=null;
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){ContextUniversalSignedUnitRounds.Result r=run(x,order,p,16);require(r.status==ContextUniversalSignedUnitRounds.Status.STABLE_UNIT_POOLS&&r.completedRounds==2&&r.refutations.isEmpty(),"current exact unit-only projection stabilizes, NOT a full-family PASS: "+r.reason);require(r.output.packet.items.size()==1&&r.symbolicOutput.units.stream().noneMatch(v->v.clause.literals.size()>1),"no compound residue or raw b/not-r enters unit/common outputs");Result donor=r.history.get(0).checks.get(Cut.of(a));Proof candidate=residual(donor,base);require(candidate.support.depth==1&&candidate.clause.literals.size()==2&&candidate.clause.variables.size()==1&&candidate.support.sources.stream().anyMatch(s->s.localX),"actual checked universal b->r at1/exact p-X+A Sources");require(candidate.horn.original!=null&&candidate.horn.original.original.source.equals(as)&&candidate.horn.original.parts.size()==(bundled?3:1),"whole physical A row remains authenticated, no per-clause Sources");if(bundled){require(donor.proofs.stream().anyMatch(v->v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals("hidden")&&v.support.sources.equals(Collections.singleton(as))&&v.support.sources.stream().noneMatch(z->z.localX)),"unrelated hidden fact shares the physical A Source but has NO X-dependent proof");require(r.output.packet.items.stream().noneMatch(v->v.atom.predicate.equals("hidden")),"whole-Source authentication does not communalize unrelated members of that row");}require(!donor.xRefuted&&!donor.foreignRefuted&&!r.history.get(0).checks.get(Cut.of(b)).xRefuted&&!r.history.get(0).checks.get(Cut.of(b)).foreignRefuted,"both ORIGINAL A-X and B-X separately consistent");require(r.symbolicOutput.units.stream().noneMatch(v->v.clause.equivalent(candidate.clause,()->{})),"specific checked compound proof is withheld by collector scope");if(first!=null){require(ContextWitnessResultTransport.sameContents(first.output.packet,r.output.packet,WORK)&&ContextUniversalSignedUnitExchange.sameContents(first.symbolicOutput,r.symbolicOutput,WORK),"unit stability independent of the two cut orders");}else first=r;carried=candidate;receiver=r.history.get(0).checks.get(Cut.of(b));
            Map<Cut,Packet> outputs=new LinkedHashMap<>();for(Map.Entry<Cut,ConstraintTransfer> e:r.output.branches.entrySet())outputs.put(e.getKey(),e.getValue().output);require(ContextWitnessResultTransport.family(r.history.get(r.history.size()-1).input,new ArrayList<>(outputs.keySet()),WORK).finish(outputs,WORK).status==FamilyStatus.INCOMPLETE,"stable unit pools never grant family finish/STEP/admission");}
        nativeDonor(x,a,p,carried);nativeReceiver(x,b,carried,false);nativeReceiver(x,b,carried,true);
        Proof bp=receiver.proofs.stream().filter(v->v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals("b")&&v.clause.literals.get(0).positive).findFirst().get();Proof nr=receiver.proofs.stream().filter(v->v.clause!=null&&v.clause.literals.size()==1&&v.clause.literals.get(0).predicate.equals("r")&&!v.clause.literals.get(0).positive).findFirst().get();int pivot=0;while(!carried.clause.literals.get(pivot).predicate.equals("b"))++pivot;Residual out=ContextUniversalInputResiduals.resolveSignedUnit(bp.clause,carried.clause,pivot,()->{});require(out!=null&&out.variables.isEmpty()&&out.literals.size()==1&&out.literals.get(0).predicate.equals("r"),"actual B unit discharges carried principal residual to r(1)");require(ContextUniversalInputResiduals.resolveSignedUnit(nr.clause,out,0,()->{})==null,"actual B not-r closes the diagnostic sequential proof");int sequential=Math.max(Math.max(bp.support.depth,carried.support.depth)+1,nr.support.depth)+1;Set<Source> sources=new HashSet<>(carried.support.sources);sources.addAll(bp.support.sources);sources.addAll(nr.support.sources);require(sequential==3&&sources.size()==4,"literal residual transport would retain honest sequential empty3/four Sources");
        Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,b),WORK);Result full=close(x,group,p);require(full.xRefuted&&full.emptyProofs.stream().anyMatch(v->v.support.depth==2&&v.support.sources.equals(sources)),"same-cut checked native-application recipe has exact empty2/SAME Sources, so carrier grade must not be relabelled");Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof proof:ContextUniversalFrozenConstraints.rejectionEvidence(full,WORK))ContextUniversalInstantiatedUnitApplicationsRunner.audit(proof,seen);
    }
    static void alternativesAndIndependence()throws Exception {
        Snapshot x=bind(true,"!anchor(1);"+P),a=bind(false,RULE),loop=bind(false,"!@u p(u)->p(u);"),b=bind(false,"!b(1); !~r(1);");Snapshot group=ContextProductionNativeBinding.trusted("own",Arrays.asList(a,loop),WORK);Packet p=ContextPrivateWitnessPoolRunner.common(x);ContextUniversalSignedUnitRounds.Result r=run(x,Arrays.asList(group,b),p,1);require(r.status==ContextUniversalSignedUnitRounds.Status.STABLE_UNIT_POOLS,"unit scope at bound1 ignores non-unit depth2 by explicit scope, not compound coverage");Residual wanted=shape();List<Proof> alternatives=new ArrayList<>();for(Proof v:r.history.get(0).checks.get(Cut.of(group)).proofs)if(v.clause!=null&&v.clause.equivalent(wanted,()->{}))alternatives.add(v);require(alternatives.size()==2&&alternatives.stream().anyMatch(v->v.support.depth==1&&v.support.sources.size()==2)&&alternatives.stream().anyMatch(v->v.support.depth==2&&v.support.sources.size()==3),"compound base1 and Source superset2 retained in owning ledger; future compound bounds must cover BOTH");
        Snapshot anchor=bind(true,"!anchor(1);"),own=bind(false,P+RULE);Packet ap=ContextPrivateWitnessPoolRunner.common(anchor);ContextUniversalSignedUnitRounds.Result independent=run(anchor,Arrays.asList(own,b),ap,16);require(independent.status==ContextUniversalSignedUnitRounds.Status.STABLE_UNIT_POOLS&&independent.completedRounds==1&&independent.symbolicOutput.units.isEmpty()&&independent.output.packet.items.size()==1,"independent siblings may disagree, unrelated X anchor cannot communalize foreign-only conditional");List<Proof> local=new ArrayList<>();for(Proof v:independent.history.get(0).checks.get(Cut.of(own)).proofs)if(v.clause!=null&&v.clause.equivalent(wanted,()->{}))local.add(v);require(!local.isEmpty()&&local.stream().allMatch(v->v.support.sources.stream().noneMatch(s->s.localX)),"same useful foreign-only residual is NOT eligible for common X exchange");
        Snapshot unsafe=ContextProductionNativeBinding.trusted("own",Arrays.asList(own,b),WORK);Result raw=close(anchor,unsafe,ap);require(raw.foreignRefuted&&!raw.xRefuted,"raw trusted union can refute foreign siblings, not authority to share their independent knowledge");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("compound-residual-evidence-").toString());one(false);one(true);alternativesAndIndependence();System.out.println("CONTEXT_UNIVERSAL_COMPOUND_RESIDUAL_EVIDENCE_PASS checks="+(checks+ContextUniversalInstantiatedUnitApplicationsRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
